/**
 * Character sprite sheet (C). Original art, generated by scripts/generate-characters.py.
 * Same pixel scale as the office map: one frame = 32×48 px in map space (1280×768).
 *
 * Sheet: /sprites/characters.png, 256×1728 = 8 columns × 36 rows of 32×48 frames.
 *   columns: 0 idle | 1–4 walk | 5 sit | 6–7 type
 *   rows:    variant * 4 + direction  (direction order: down, left, right, up)
 */
export const CHARACTER_SHEET = {
  src: '/sprites/characters.png',
  frameWidth: 32,
  frameHeight: 48,
  columns: 8,
  rows: 36,
  variants: 9,
  directions: ['down', 'left', 'right', 'up'] as const,
  frames: { idle: [0], walk: [1, 2, 3, 4], sit: [5], type: [6, 7] },
} as const

export type Direction = (typeof CHARACTER_SHEET.directions)[number]
export type Animation = keyof typeof CHARACTER_SHEET.frames

/**
 * Fixed looks for the demo personas, so the people on stage are recognisable and distinct
 * (the hash alone gave Alia, Aina and Shane the same sprite).
 * Variants: 0 short black/blue · 1 hijab maroon · 2 short black/green · 3 long black/mustard ·
 *           4 short brown/grey · 5 hijab teal · 6 short black/red · 7 long brown/orange ·
 *           8 boss: dark suit + red tie (John only; never picked at random)
 * Alia, Shane and Raeisya are real people: each picks their own; these are placeholders.
 */
const PERSONA_VARIANTS: Record<string, number> = {
  'u-alia': 5,
  'u-shane': 4,
  'u-raeisya': 0,
  'u-hafiz': 6,
  'u-aina': 1,
  'u-john': 8,
}

/** Variants handed out by hash: everything except the boss suit. */
const RANDOM_VARIANTS = 8

/** Stable sprite variant per person (same user → same look on every render). */
export function variantFor(userId: string): number {
  if (userId in PERSONA_VARIANTS) return PERSONA_VARIANTS[userId]
  let h = 0
  for (let i = 0; i < userId.length; i++) h = (h * 31 + userId.charCodeAt(i)) | 0
  return Math.abs(h) % RANDOM_VARIANTS
}

/**
 * CSS for one frame, scale-independent: size the element to 32×48 map px (as % of the map,
 * like the desks) and this picks the frame with percentage background maths.
 */
export function frameStyle(variant: number, direction: Direction, column: number) {
  const { columns, rows, src, directions } = CHARACTER_SHEET
  const row = variant * directions.length + directions.indexOf(direction)
  return {
    backgroundImage: `url("${src}")`,
    backgroundSize: `${columns * 100}% ${rows * 100}%`,
    backgroundPosition: `${(column / (columns - 1)) * 100}% ${(row / (rows - 1)) * 100}%`,
    imageRendering: 'pixelated' as const,
  }
}

/**
 * Where a seated person goes, in map px (top-left of the 32×48 frame), for a desk from /api/floor.
 * facing 'down' → chair is the top half of the desk cell, person seen from the front (use direction 'down').
 * facing 'up'   → chair is the bottom half, person seen from behind (use direction 'up').
 */
export function seatPosition(desk: { x: number; y: number; facing: 'up' | 'down' }) {
  return desk.facing === 'down' ? { x: desk.x + 16, y: desk.y - 20 } : { x: desk.x + 16, y: desk.y + 16 }
}

/** Standing/walking: put the frame's bottom-centre on the feet point → top-left = (fx - 16, fy - 44). */
export function standPosition(feetX: number, feetY: number) {
  return { x: feetX - 16, y: feetY - 44 }
}
